def _valid_atom_hash(atom: Mapping[str, Any]) -> bool:
    """Check the hash emitted by :class:`src.calculator.atomizer.Atom`."""
    record = {key: atom.get(key) for key in ('atom_id', 'behavior', 'source', 'name', 'values', 'units', 'evidence')}
    expected = hashlib.sha256(json.dumps(record, sort_keys=True, separators=(',', ':')).encode()).hexdigest()[:16]
    return str(atom.get('hash', '')) == expected

